package edu.ku.commerce.omnichannel_commerce.cart; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; public interface CartRepository extends JpaRepository<Cart,Long>{ @Query("SELECT c FROM Cart c LEFT JOIN FETCH c.items WHERE c.customerId = ?1 AND c.channel = ?2") Optional<Cart> findByCustomerIdAndChannel(Long customerId,String channel); @Query("SELECT c FROM Cart c LEFT JOIN FETCH c.items WHERE c.id = ?1") Optional<Cart> findById(Long id); }
